SELECT c.*, UNIX_TIMESTAMP(c.open_time) AS open_epoch_utc FROM crypto_ai.candle c WHERE c.interval_code='1m' AND ((c.symbol='EGLDUSDT' AND c.open_time BETWEEN '2026-10-11 20:49:00' AND '2026-10-11 20:55:00') OR (c.symbol='EGLDUSDT' AND c.open_time BETWEEN '2026-10-11 22:34:00' AND '2026-10-11 22:40:00') OR (c.symbol='XRPUSDT' AND c.open_time BETWEEN '2026-10-12 02:29:00' AND '2026-10-12 02:35:00') OR (c.symbol='DOGEUSDT' AND c.open_time BETWEEN '2026-10-12 03:56:00' AND '2026-10-12 04:02:00') OR (c.symbol='SHIBUSDT' AND c.open_time BETWEEN '2026-10-12 06:30:00' AND '2026-10-12 06:36:00') OR (c.symbol='ACEUSDT' AND c.open_time BETWEEN '2026-10-12 09:51:00' AND '2026-10-12 09:57:00')) ORDER BY c.symbol, c.open_time LIMIT 60;